/**
 * Navigation as text, with an optional Button-styled variant (`design/components/link.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/link.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  Icon,
  MEMBER_PROVIDERS,
  Ref,
  SlotOutlet,
  SlotTemplate,
  agentMember,
  agentPress,
  derived,
  elementRef,
  mountEffect,
  useMember,
  type IconProps,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/controls/link.module.css'

export type LinkVariant = NonNullable<LinkProps['variant']>

export interface LinkButtonGrid {
  solid: 'accent'
  soft: 'accent'
  outline: 'accent' | 'neutral'
  ghost: 'accent' | 'neutral'
}

/** Navigation as text, with an optional Button-styled variant: the inputs it takes, by the React member's prop names. */
export interface LinkProps {
  buttonVariant?: 'solid' | 'soft' | 'outline' | 'ghost'
  /**
   * Adds the glyph, the new tab, and the `rel` that makes it safe.
   */
  external?: boolean
  href: string
  /**
   * Control size, as on Button.
   */
  size?: 'sm' | 'md' | 'lg'
  tone?: 'accent' | 'neutral'
  /**
   * `inline` sits inside a sentence and `standalone` is a row or a title.
   */
  variant?: 'inline' | 'standalone' | 'button'
}

/** Navigation as text, with an optional Button-styled variant. */
@Component({
  selector: 'pm-link',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  imports: [Ref, SlotOutlet, SlotTemplate, Icon],
  // prettier-ignore
  template: `<ng-template pmSlot="default" [pmSlotOf]="$"><ng-content /></ng-template>
@if (e1()) {<a
[attr.class]="e2()"
[attr.href]="e3()"
[attr.data-variant]="e4()"
[attr.data-tone]="e5()"
[attr.data-size]="e6()"
[attr.data-external]="e7()"
[attr.target]="e8()"
[attr.rel]="e9()"
data-member="link"
(click)="h1($event)"
[pmRef]="control"
><!-- label -->
<span
[attr.class]="e10()"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" /></span>
@if (e11()) {<!-- glyph -->
<span
[attr.class]="e12()"
><pm-icon
name="open-external"
[size]="e13()"
></pm-icon></span>}</a>} @else {<a
[attr.class]="e14()"
[attr.href]="e15()"
[attr.data-variant]="e16()"
[attr.data-external]="e17()"
[attr.target]="e18()"
[attr.rel]="e19()"
data-member="link"
(click)="h2($event)"
[pmRef]="control"
><ng-container [pmSlotOutlet]="'default'" [pmSlotOf]="$" />
@if (e20()) {<pm-icon
name="open-external"
size="sm"
></pm-icon>}</a>}`,
})
export class Link {
  readonly buttonVariant = input<
    Exclude<LinkProps['buttonVariant'], undefined>,
    LinkProps['buttonVariant']
  >('soft', {
    transform: (value: LinkProps['buttonVariant']) => (value === undefined ? 'soft' : value),
  })
  /**
   * Adds the glyph, the new tab, and the `rel` that makes it safe.
   */
  readonly external = input<Exclude<LinkProps['external'], undefined>, LinkProps['external']>(
    false,
    { transform: (value: LinkProps['external']) => (value === undefined ? false : value) },
  )
  readonly href = input.required<LinkProps['href']>()
  /**
   * Control size, as on Button.
   */
  readonly size = input<Exclude<LinkProps['size'], undefined>, LinkProps['size']>('md', {
    transform: (value: LinkProps['size']) => (value === undefined ? 'md' : value),
  })
  readonly tone = input<Exclude<LinkProps['tone'], undefined>, LinkProps['tone']>('accent', {
    transform: (value: LinkProps['tone']) => (value === undefined ? 'accent' : value),
  })
  /**
   * `inline` sits inside a sentence and `standalone` is a row or a title.
   */
  readonly variant = input<Exclude<LinkProps['variant'], undefined>, LinkProps['variant']>(
    'inline',
    { transform: (value: LinkProps['variant']) => (value === undefined ? 'inline' : value) },
  )
  /**
   * The app's router. A click the browser would follow in this tab calls it with `href` in place
   * of the browser's navigation; a click with a modifier key or another button, and a click on
   * an `external` link, stay the browser's. It routes and does nothing else: a click that
   * changes data is a Button.
   */
  readonly onNavigate = output<string>({ alias: 'navigate' })
  protected readonly $ = useMember({
    events: ['navigate'],
    props: {
      buttonVariant: () => this.buttonVariant(),
      external: () => this.external(),
      href: () => this.href(),
      size: () => this.size(),
      tone: () => this.tone(),
      variant: () => this.variant(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly control = elementRef<HTMLElement>()
  protected readonly navigatesHere = derived(
    () =>
      (event: MouseEvent): boolean =>
        !event.defaultPrevented &&
        event.button === 0 &&
        !event.metaKey &&
        !event.ctrlKey &&
        !event.shiftKey &&
        !event.altKey,
  )
  protected readonly route = derived(() => (event: MouseEvent): void => {
    if (this.$p.external || !this.navigatesHere.value(event)) return
    event.preventDefault()
    this.$.emit(this.onNavigate, 'onNavigate', this.$p.href)
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    mountEffect(() => this.effect1())
  }

  protected e1() {
    return this.$p.variant === 'button'
  }

  protected e2() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return styles.costume
  }

  protected e3() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.href
  }

  protected e4() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.buttonVariant
  }

  protected e5() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.tone
  }

  protected e6() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.size
  }

  protected e7() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.external ? '' : undefined
  }

  protected e8() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.external ? '_blank' : undefined
  }

  protected e9() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.external ? 'noreferrer' : undefined
  }

  protected h1($event: MouseEvent): void {
    if (!(this.$p.variant === 'button')) return
    if (this.$.listening(this.onNavigate, 'onNavigate')) {
      this.route.value($event)
    }
  }

  protected e10() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return styles.costumeLabel
  }

  protected e11() {
    if (!(this.$p.variant === 'button')) return undefined as never
    return this.$p.external
  }

  protected e12() {
    if (!(this.$p.variant === 'button')) return undefined as never
    if (!this.$p.external) return undefined as never
    return styles.costumeGlyph
  }

  protected e13(): IconProps['size'] {
    if (!(this.$p.variant === 'button')) return undefined as never
    if (!this.$p.external) return undefined as never
    return this.$p.size
  }

  protected e14() {
    if (this.$p.variant === 'button') return undefined as never
    return styles.link
  }

  protected e15() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.href
  }

  protected e16() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.variant
  }

  protected e17() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.external ? '' : undefined
  }

  protected e18() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.external ? '_blank' : undefined
  }

  protected e19() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.external ? 'noreferrer' : undefined
  }

  protected h2($event: MouseEvent): void {
    if (this.$p.variant === 'button') return
    if (this.$.listening(this.onNavigate, 'onNavigate')) {
      this.route.value($event)
    }
  }

  protected e20() {
    if (this.$p.variant === 'button') return undefined as never
    return this.$p.external
  }

  private effect1(): void {
    this.release1?.()
    const ran = agentMember({
      member: 'Link',
      element: () => this.control.value,
      state: () => ({ external: this.$p.external }),
      actions: {
        press: () =>
          (() => {
            if (this.$p.external)
              throw new Error(
                'An external link opens a new tab, which only a person’s press opens.',
              )
            agentPress(this.control.value)
          })(),
      },
    })
    this.release1 = () => {
      ran()
    }
  }
}
